    }
    $zip = Join-Path $env:TEMP ($_.Replace('/','-') + ".zip")
    Write-Host "DL $repo ..."
    Invoke-WebRequest -Uri "https://github.com/$repo/archive/refs/heads/main.zip" -OutFile $zip -UseBasicParsing
    $extract = Join-Path $env:TEMP ($_ + "-extract")
    if (Test-Path $extract) { Remove-Item $extract -Recurse -Force }
    Expand-Archive $zip $extract -Force
    $inner = Get-ChildItem $extract -Directory | Select-Object -First 1
    if (Test-Path $dest) { Remove-Item $dest -Recurse -Force }
    Move-Item $inner.FullName $dest -Force
    Write-Host "Ready $dest"
  } else { Write-Host "Exists $dest" }
}

