function Ensure-Junction($src, $dest) {
  if (Test-Path $dest) {
    $item = Get-Item $dest -Force
    if ($item.LinkType -eq 'Junction') { cmd /c rmdir `"$dest`" 2>$null }
    elseif ($item.PSIsContainer) { Copy-Item $dest (Join-Path $backup ($(Split-Path $dest -Leaf))) -Recurse -Force -ErrorAction SilentlyContinue; Remove-Item $dest -Recurse -Force }
    else { Remove-Item $dest -Force }
  }
  New-Item -ItemType Junction -Path $dest -Target $src | Out-Null
  Write-Host "Junction $dest -> $src"
}

